package com.miayang.ecommerce.order.client;

import java.math.BigDecimal;
import java.util.Collection;
import java.util.List;

import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * HTTP client for product-service, generated by OpenFeign from this interface.
 * name = "product-service" is looked up in Eureka, so no host or port is hard-coded.
 * Timeouts: config-repo/order-service.yml.
 */
@FeignClient(name = "product-service", path = "/internal")
public interface ProductServiceClient {

    @PostMapping("/products/lookup")
    List<ProductSnapshot> lookup(@RequestBody ProductLookupRequest request);

    @PostMapping("/stock/reservations")
    void reserve(@RequestBody StockRequest request);

    @PostMapping("/stock/releases")
    void release(@RequestBody StockRequest request);

    // order-service's own copy of product-service's JSON shapes (services share JSON, not Java classes).

    record ProductLookupRequest(Collection<Long> productIds) {
    }

    record ProductSnapshot(Long id, String name, BigDecimal price) {
    }

    record StockLine(Long productId, int quantity) {
    }

    record StockRequest(List<StockLine> items) {
    }
}
